namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications;
    private int _nextId;

    public NotificationService()
    {
        _notifications = new List<Notification>
        {
            new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-20)),
            new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-10)),
        };
        _nextId = 4;
    }

    /// <summary>Returns all notifications available right now.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int sinceId)
    {
        // Simulate a new notification roughly every other poll
        MaybeAddFakeNotification();

        lock (_notifications)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > sinceId).ToList());
        }
    }

    private void MaybeAddFakeNotification()
    {
        if (Random.Shared.NextDouble() < 0.5)
            return;

        lock (_notifications)
        {
            var id = _nextId++;
            _notifications.Add(new Notification(
                id,
                $"Something happened — notification #{id}",
                DateTime.UtcNow));
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState PersistState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        // During prerender the PersistentComponentState won't have our data yet,
        // so we load from the service and register a callback to persist it.
        // When the page becomes interactive (second OnInitialized), we restore
        // from persisted state instead of hitting the service again.
        _persistSub = PersistState.RegisterOnPersisting(PersistNotifications);

        if (PersistState.TryTakeFromJson<List<Notification>>(
                "notifications", out var restored))
        {
            notifications = restored!;
        }
        else
        {
            notifications = await NotificationSvc.GetNotificationsAsync();
        }
    }

    private Task PersistNotifications()
    {
        PersistState.PersistAsJson("notifications", notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender only fires on the interactive circuit, never during
        // static SSR, so this is the safe place to start the polling loop.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var latestId = notifications.Count > 0
                    ? notifications.Max(n => n.Id)
                    : 0;

                var newer = await NotificationSvc.GetNotificationsSinceAsync(latestId);

                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

